    {
      "keystrokes": "python3 - <<'EOF'\nfrom transformers import AutoModel, AutoTokenizer\nm = AutoModel.from_pretrained(\"albert/albert-base-v2\")\nt = AutoTokenizer.from_pretrained(\"albert/albert-base-v2\")\nprint(\"DOWNLOAD_OK\", m.config.model_type, len(t))\nEOF\n",
      "duration": 45.0
    }
  ]
