    {
      "keystrokes": "HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 python3 - <<'EOF'\nfrom transformers import AutoModel, AutoTokenizer\nimport torch\nm = AutoModel.from_pretrained(\"albert/albert-base-v2\")\nt = AutoTokenizer.from_pretrained(\"albert/albert-base-v2\")\nx = t(\"Hello, this is a test for offline use.\", return_tensors=\"pt\")\nwith torch.no_grad():\n    out = m(**x)\nprint(\"OFFLINE_OK\", out.last_hidden_state.shape)\nEOF\n",
      "duration": 20.0
    }
  ]
}

